#include <iostream>
#include <utility>

using namespace std;

using pos = pair<long long, long long>;

long long gcd(long long a, long long b) {
    if (a < 0) a = -a;
    if (b < 0) b = -b;

    while (b != 0) {
        long long remainder = a % b;
        a = b;
        b = remainder;
    }

    return a;
}

pos simplify(pos a) {
    if (a.first == 0 && a.second != 0) {
        a.second = 1;
        return a;
    }

    if (a.first != 0 && a.second == 0) {
        a.first = 1;
        return a;
    }

    if (a.first == 0 && a.second == 0) {
        return a;
    }

    if (a.first < 0 && a.second < 0) {
        a.first = -a.first;
        a.second = -a.second;
    }

    long long divisor = gcd(a.first, a.second);
    a.first /= divisor;
    a.second /= divisor;

    return a;
}

int main() {
    pos a, b, c;

    cin >> a.first >> a.second
        >> b.first >> b.second
        >> c.first >> c.second;

    pos ab = {a.first - b.first, a.second - b.second};
    pos bc = {b.first - c.first, b.second - c.second};

    cout << (simplify(ab) == simplify(bc) ? "No" : "Yes") << '\n';

    return 0;
}

